/* ==========================================================================
   A partir de aquí, capítulos largos.

   Los primeros resúmenes tenían capítulos de un minuto, y en el camino eso
   se leía mal: un nodo con candado y una meta al final prometen una etapa,
   no un párrafo. Estos llevan capítulos de dos minutos y medio o tres, con
   su propio arco — abren con una escena, desarrollan y cierran—, de modo
   que cada parada valga por sí sola aunque se lea suelta.
   ========================================================================== */

